# Generated by ttrek gen-script. Run from any directory.
# Match the SDK to the selected Xcode compiler, rather than its fallback SDK.
if [ "$(uname -s)" = Darwin ]; then
    SDKROOT=${SDKROOT:-$(xcrun --sdk macosx --show-sdk-path)}
    export SDKROOT
fi

PROJECT_HOME="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)"
ROOT_BUILD_DIR="$PROJECT_HOME/build"
INSTALL_DIR="$ROOT_BUILD_DIR/install"
DOWNLOAD_DIR="$ROOT_BUILD_DIR/download"
PATCH_DIR="$ROOT_BUILD_DIR/source"
DEFAULT_THREADS=${TTREK_MAKE_THREADS:-4}

export PROJECT_HOME
export PATH="$INSTALL_DIR/bin:$PATH"
export LD_LIBRARY_PATH="$INSTALL_DIR/lib:$INSTALL_DIR/lib64${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
export PKG_CONFIG_PATH="$INSTALL_DIR/lib/pkgconfig:$INSTALL_DIR/lib64/pkgconfig${PKG_CONFIG_PATH:+:$PKG_CONFIG_PATH}"
mkdir -p "$DOWNLOAD_DIR" "$PATCH_DIR" "$INSTALL_DIR"

unpack() (
    archive=$1
    destination=$2
    if tar -tzf "$archive" >/dev/null 2>&1; then
        tar -xzf "$archive" --strip-components=1 -C "$destination"
    else
        unzip -q "$archive" -d "$destination" || exit $?
        # Source archives contain one top-level directory.
        for directory in "$destination"/*; do
            [ -d "$directory" ] || continue
            cp -R "$directory"/. "$destination"/ || exit $?
            rm -rf "$directory" || exit $?
            break
        done
    fi
)
